package com.forgebuild.engine.ui.icons

import androidx.compose.ui.graphics.vector.ImageVector

/**
 * Material Symbols icon set bundled locally (offline-friendly, no runtime font).
 * Icon glyphs are generated by tools/gen_icons.py which converts Material
 * Symbols SVG path data into Compose ImageVectors in EngineIconsGenerated.kt.
 * Generated apps: NEVER use emoji or mismatched icon sets for iconography —
 * extend this set via tools/gen_icons.py instead.
 */
object EngineIcons {
    val Bolt: ImageVector get() = EngineIconsGenerated.Bolt
    val Settings: ImageVector get() = EngineIconsGenerated.Settings
    val Add: ImageVector get() = EngineIconsGenerated.Add
    val Home: ImageVector get() = EngineIconsGenerated.Home
    val Search: ImageVector get() = EngineIconsGenerated.Search
    val ArrowBack: ImageVector get() = EngineIconsGenerated.ArrowBack
    val DesktopWindows: ImageVector get() = EngineIconsGenerated.DesktopWindows
    val Delete: ImageVector get() = EngineIconsGenerated.Delete
    val Edit: ImageVector get() = EngineIconsGenerated.Edit
    val MoreVert: ImageVector get() = EngineIconsGenerated.MoreVert
    val ContentCopy: ImageVector get() = EngineIconsGenerated.ContentCopy
    val Close: ImageVector get() = EngineIconsGenerated.Close
    val Sync: ImageVector get() = EngineIconsGenerated.Sync
    val Security: ImageVector get() = EngineIconsGenerated.Security
    val Image: ImageVector get() = EngineIconsGenerated.Image
    val Movie: ImageVector get() = EngineIconsGenerated.Movie
    val Camera: ImageVector get() = EngineIconsGenerated.Camera
    val Folder: ImageVector get() = EngineIconsGenerated.Folder
    val FolderOpen: ImageVector get() = EngineIconsGenerated.FolderOpen
    val Crop: ImageVector get() = EngineIconsGenerated.Crop
    val AddPhotoAlternate: ImageVector get() = EngineIconsGenerated.AddPhotoAlternate
    val Undo: ImageVector get() = EngineIconsGenerated.Undo
    val Redo: ImageVector get() = EngineIconsGenerated.Redo
    val KeyboardArrowUp: ImageVector get() = EngineIconsGenerated.KeyboardArrowUp
    val KeyboardArrowDown: ImageVector get() = EngineIconsGenerated.KeyboardArrowDown
    val ExpandLess: ImageVector get() = EngineIconsGenerated.ExpandLess
    val ExpandMore: ImageVector get() = EngineIconsGenerated.ExpandMore
    val Fullscreen: ImageVector get() = EngineIconsGenerated.Fullscreen
    val FileDownload: ImageVector get() = EngineIconsGenerated.FileDownload
    val CheckCircle: ImageVector get() = EngineIconsGenerated.CheckCircle
    val MenuBook: ImageVector get() = EngineIconsGenerated.MenuBook
}
